    "sql": "WITH \"__weft_temporal_source\" AS MATERIALIZED (SELECT id,props FROM \"truss\".\"person_query_temporal_objects\"($1::pg_catalog.jsonb,1::pg_catalog.int4,$2::pg_catalog.jsonb)) SELECT pg_catalog.to_jsonb((\"__weft_temporal_source\".props->E'3')->>'text')::pg_catalog.text AS \"day\",pg_catalog.to_jsonb((\"__weft_temporal_source\".props->E'4')->>'text')::pg_catalog.text AS \"at\",(CASE WHEN \"__weft_temporal_source\".props->E'5' IS NULL THEN pg_catalog.jsonb_build_object('state','absent') WHEN (\"__weft_temporal_source\".props->E'5')->>'kind'='null' THEN pg_catalog.jsonb_build_object('state','null') ELSE pg_catalog.jsonb_build_object('state','value','value',pg_catalog.to_jsonb((\"__weft_temporal_source\".props->E'5')->>'text')) END)::pg_catalog.text AS \"wall\" FROM \"__weft_temporal_source\" WHERE ((CASE WHEN \"__weft_temporal_source\".props->E'4' IS NULL OR (\"__weft_temporal_source\".props->E'4')->>'kind'='null' THEN NULL ELSE \"truss\".\"query_temporal_canonical_text\"(E'instant',(\"__weft_temporal_source\".props->E'4')->>'text') END) COLLATE \"C\" >= \"truss\".\"query_temporal_canonical_text\"(E'instant',$3::pg_catalog.text) COLLATE \"C\") ORDER BY (CASE WHEN \"__weft_temporal_source\".props->E'5' IS NULL OR (\"__weft_temporal_source\".props->E'5')->>'kind'='null' THEN NULL ELSE \"truss\".\"query_temporal_canonical_text\"(E'local',(\"__weft_temporal_source\".props->E'5')->>'text') END) COLLATE \"C\" DESC NULLS FIRST,(CASE WHEN \"__weft_temporal_source\".props->E'3' IS NULL OR (\"__weft_temporal_source\".props->E'3')->>'kind'='null' THEN NULL ELSE \"truss\".\"query_temporal_canonical_text\"(E'date',(\"__weft_temporal_source\".props->E'3')->>'text') END) COLLATE \"C\" ASC NULLS LAST",
