1')->>'kind'='null' THEN NULL ELSE (\"__weft_temporal_source\".props->E'1')->>'text' END) COLLATE \"C\" ASC NULLS LAST,(CASE WHEN \"__weft_temporal_source\".props->E'2' IS NULL OR (\"__weft_temporal_source\".props->E'2')->>'kind'='null' THEN NULL ELSE (\"__weft_temporal_source\".props->E'2')->>'text' END) COLLATE \"C\" ASC NULLS LAST LIMIT 3",
